SELECT c.conversation_id, c.owner_user_id, c.agent_id, c.agent_instance_id, c.project_id, c.chain_id, c.title, c.unread_count, c.last_message_preview, c.last_message_at, c.created_at, c.updated_at, c.last_activity_at, c.last_title_nudge_at, c.title_source, COALESCE((SELECT m.message_id FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), ''), COALESCE((SELECT m.direction FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), ''), COALESCE((SELECT m.sender_agent_id FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), ''), COALESCE((SELECT m.sender_agent_instance_id FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), ''), COALESCE((SELECT COALESCE(m.message_type, 'text') FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), 'text'), COALESCE((SELECT COALESCE(m.message_status, 'complete') FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), 'complete'), COALESCE((SELECT m.created_at FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent' ORDER BY m.created_at DESC, m.message_id DESC LIMIT 1), c.last_message_at), (SELECT COUNT(*) FROM chat_messages m WHERE m.conversation_id=c.conversation_id AND m.owner_user_id=c.owner_user_id AND m.direction != 'agent_to_agent') FROM chat_conversations c WHERE c.owner_user_id='index-owner' ORDER BY COALESCE(NULLIF(c.last_message_at,''), c.updated_at, c.created_at) DESC, c.conversation_id DESC LIMIT 200;
